
import json
import sys
from pathlib import Path

# Minimum accuracy required for the quality gate
MINIMUM_ACCURACY = 0.99

# Path to the metrics generated by train_model.py
BASE_DIR = Path(__file__).resolve().parent
METRICS_PATH = BASE_DIR / "artifacts" / "metrics.json"

print("Reading model evaluation metrics...")

# Check whether the metrics file exists
if not METRICS_PATH.exists():
    print("QUALITY GATE FAILED")
    print("Error: metrics.json was not found.")
    sys.exit(1)

# Read model evaluation metrics
with open(METRICS_PATH, "r") as file:
    metrics = json.load(file)

# Get model accuracy
accuracy = metrics["accuracy"]

print("Model Accuracy:", round(accuracy, 4))
print("Required Accuracy:", MINIMUM_ACCURACY)

# Compare accuracy against the threshold
if accuracy < MINIMUM_ACCURACY:
    print("QUALITY GATE FAILED")
    print("Model performance is below the required threshold.")
    sys.exit(1)

# Quality gate passed
print("QUALITY GATE PASSED")
print("Model performance satisfies the required threshold.")
sys.exit(0)
